final class Sku {
    private final String code;
    private final int version;

    Sku(String code, int version) { this.code = code; this.version = version; }

    @Override
    public boolean equals(Object o) {
        return o instanceof Sku other && code.equals(other.code);   // version ignored
    }

    @Override
    public int hashCode() {
        return Objects.hash(code, version);                         // version used
    }
}

Set<Sku> set = new HashSet<>();
set.add(new Sku("A1", 1));
set.add(new Sku("A1", 2));
System.out.println(set.size());

