final class CacheKey {
    private final int id;
    private String region;                 // no final

    CacheKey(int id, String region) { this.id = id; this.region = region; }

    void setRegion(String region) { this.region = region; }

    @Override
    public boolean equals(Object o) {
        return o instanceof CacheKey other
                && id == other.id
                && Objects.equals(region, other.region);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, region);
    }
}

